/* Eclipse Paho MQTT over WebSocket - Direct Engine */
(function() {
  'use strict';

  function Client(host, port, path, clientId) {
    if (!path || path.indexOf('/') !== 0) {
      path = '/mqtt';
    }
    this.host = host;
    this.port = Number(port);
    this.path = path;
    this.clientId = clientId || ('c_' + Math.random().toString(36).substr(2, 8));
    this.connected = false;
    this.socket = null;
    this.onConnectionLost = null;
    this.onMessageArrived = null;
    this._pingTimer = null;
  }

  Client.prototype.connect = function(options) {
    options = options || {};
    var self = this;
    var proto = options.useSSL ? 'wss://' : 'ws://';
    var url = proto + self.host + ':' + self.port + self.path;

    try {
      self.socket = new WebSocket(url, ['mqttv3.1', 'mqtt']);
    } catch (e) {
      if (options.onFailure) options.onFailure({ errorCode: 7, errorMessage: e.message });
      return;
    }

    self.socket.binaryType = 'arraybuffer';

    var timer = setTimeout(function() {
      if (!self.connected) {
        try { self.socket.close(); } catch (err) {}
        if (options.onFailure) options.onFailure({ errorCode: 1, errorMessage: 'Timeout' });
      }
    }, (options.timeout || 10) * 1000);

    self.socket.onopen = function() {
      var vHeader = [0x00, 0x04, 0x4D, 0x51, 0x54, 0x54, 0x04, 0x02, 0x00, 0x1E];
      var id = [];
      for (var i = 0; i < self.clientId.length; i++) {
        id.push(self.clientId.charCodeAt(i));
      }
      var payload = [(id.length >> 8) & 0xFF, id.length & 0xFF].concat(id);
      var remLen = vHeader.length + payload.length;
      var lenBytes = [];
      do {
        var digit = remLen % 128;
        remLen = Math.floor(remLen / 128);
        if (remLen > 0) digit = digit | 0x80;
        lenBytes.push(digit);
      } while (remLen > 0);

      var packet = new Uint8Array([0x10].concat(lenBytes).concat(vHeader).concat(payload));
      self.socket.send(packet.buffer);
    };

    self.socket.onmessage = function(event) {
      var bytes = new Uint8Array(event.data);
      var type = (bytes[0] >> 4) & 0x0F;

      if (type === 2) { // CONNACK
        clearTimeout(timer);
        if (bytes[3] === 0) {
          self.connected = true;
          self._pingTimer = setInterval(function() {
            if (self.connected && self.socket && self.socket.readyState === 1) {
              self.socket.send(new Uint8Array([0xC0, 0x00]).buffer);
            }
          }, 25000);
          if (options.onSuccess) options.onSuccess({ invocationContext: options.invocationContext });
        } else {
          self.connected = false;
          if (options.onFailure) options.onFailure({ errorCode: bytes[3], errorMessage: 'Connack rejected' });
        }
      } else if (type === 3) { // PUBLISH
        var idx = 1;
        var multiplier = 1;
        var length = 0;
        var digit;
        do {
          digit = bytes[idx++];
          length += (digit & 127) * multiplier;
          multiplier *= 128;
        } while ((digit & 128) !== 0);

        var topicLen = (bytes[idx] << 8) | bytes[idx + 1];
        idx += 2;
        var topic = '';
        for (var t = 0; t < topicLen; t++) {
          topic += String.fromCharCode(bytes[idx++]);
        }

        var payloadStr = '';
        while (idx < bytes.length) {
          payloadStr += String.fromCharCode(bytes[idx++]);
        }
        try {
          payloadStr = decodeURIComponent(escape(payloadStr));
        } catch (e) {}

        if (self.onMessageArrived) {
          self.onMessageArrived({ destinationName: topic, payloadString: payloadStr });
        }
      }
    };

    self.socket.onclose = function() {
      clearInterval(self._pingTimer);
      self.connected = false;
      if (self.onConnectionLost) self.onConnectionLost({ errorCode: 8, errorMessage: 'Closed' });
    };

    self.socket.onerror = function(e) {
      clearInterval(self._pingTimer);
      self.connected = false;
      if (self.onConnectionLost) self.onConnectionLost({ errorCode: 7, errorMessage: 'Socket Error' });
    };
  };

  Client.prototype.subscribe = function(topic, options) {
    if (!this.connected || !this.socket) return;
    options = options || {};
    var topicBytes = [];
    for (var i = 0; i < topic.length; i++) {
      topicBytes.push(topic.charCodeAt(i));
    }
    var vHeader = [0x00, 0x01];
    var payload = [(topicBytes.length >> 8) & 0xFF, topicBytes.length & 0xFF].concat(topicBytes).concat([options.qos || 0]);
    var remLen = vHeader.length + payload.length;
    var lenBytes = [];
    do {
      var digit = remLen % 128;
      remLen = Math.floor(remLen / 128);
      if (remLen > 0) digit = digit | 0x80;
      lenBytes.push(digit);
    } while (remLen > 0);

    var packet = new Uint8Array([0x82].concat(lenBytes).concat(vHeader).concat(payload));
    this.socket.send(packet.buffer);
  };

  Client.prototype.send = function(msg) {
    if (!this.connected || !this.socket) return;
    var topicBytes = [];
    for (var i = 0; i < msg.destinationName.length; i++) {
      topicBytes.push(msg.destinationName.charCodeAt(i));
    }
    var str = unescape(encodeURIComponent(msg.payloadString));
    var payloadBytes = [];
    for (var p = 0; p < str.length; p++) {
      payloadBytes.push(str.charCodeAt(p));
    }
    var vHeader = [(topicBytes.length >> 8) & 0xFF, topicBytes.length & 0xFF].concat(topicBytes);
    var remLen = vHeader.length + payloadBytes.length;
    var lenBytes = [];
    do {
      var digit = remLen % 128;
      remLen = Math.floor(remLen / 128);
      if (remLen > 0) digit = digit | 0x80;
      lenBytes.push(digit);
    } while (remLen > 0);

    var packet = new Uint8Array([0x30].concat(lenBytes).concat(vHeader).concat(payloadBytes));
    this.socket.send(packet.buffer);
  };

  Client.prototype.disconnect = function() {
    clearInterval(this._pingTimer);
    if (this.socket && this.socket.readyState === 1) {
      try {
        this.socket.send(new Uint8Array([0xE0, 0x00]).buffer);
        this.socket.close();
      } catch (e) {}
    }
    this.connected = false;
  };

  Client.prototype.isConnected = function() {
    return this.connected;
  };

  function Message(payload) {
    this.payloadString = typeof payload === 'string' ? payload : JSON.stringify(payload);
    this.destinationName = '';
    this.qos = 0;
  }

  // Bind unconditionally to window
  window.Paho = {
    MQTT: {
      Client: Client,
      Message: Message
    }
  };
})();
